//! Single-process Verus spec projected from TLA+ module `JetpackClean`.
//!
//! Generated by `verus-transpile clean-tla`. Do not edit by hand: the
//! clean-subset spec it came from is the source of truth. Only this header is
//! written by a human; `tests/corpus/scripts/refresh_goldens.sh` replaces the
//! `verus!` block and leaves the prose alone.
//!
//! **Tier 3, and the point of the whole exercise.** Jetpack is the case Phase
//! 51 tried to do by hand and stopped partway through. `reference.rs` is that
//! attempt, and reading the two side by side is what this case is for.
//!
//! **Where they agree.** For every action Phase 51 wrote, the generated spec
//! is the same spec. `LHandlePrepareResp` and `L_HandlePrepareResp` both
//! record the responder and keep the highest-ballot value seen so far — the
//! online aggregation a real proposer does, rather than the original's stored
//! `prep_responses` map. `LCompletePrepare` and `L_CompletePrepare` both
//! count (`LIsQuorum(c, s.prep_rcvd)` / `prep_rcvd.len() >= c.quorum_size`)
//! rather than quantifying over the original's `JQuorum` powerset, and both
//! keep Paxos's safety core intact: *if any promise reported an accepted
//! value, propose that value*. `LHandleAcceptReq` and `L_HandleAcceptReq`
//! agree on the acceptor triple.
//!
//! **Where the generated spec is more complete**, because 51.9 was never
//! written: the whole BeginRecovery phase (`LSendBeginRecovery`,
//! `LHandleBeginRecoveryReq`, `LHandleBeginRecoveryResp`,
//! `LCompleteBeginRecovery`), the two remaining senders (`LSendPrepare`,
//! `LSendAccept`), `LFinishRecovery`, and the parts a hand-written spec has
//! to invent — `LMessage`, `LPacket`, the `LHandleMessage` dispatch, and
//! `LNext`.
//!
//! **Two differences that are not the translator being wrong:**
//!
//! - `L_HandlePrepareResp` guards on `s.jstate is AfterBeginRecovery` and on
//!   the responder not having been counted. The original's
//!   `HandlePrepareResponse` guards on neither — it just records — so the
//!   generated spec does not either. Phase 51 added those guards by hand;
//!   `clean.tla` is faithful to `jetpack.tla`. (Recording a responder twice
//!   is a no-op either way: a set union, like the original's map assignment,
//!   is idempotent.)
//! - The hand-written constants carry a precomputed `quorum_size`; the
//!   generated ones count, because that is what `clean.tla` says. Both are
//!   P4-shaped; one pre-computes what the other derives. Paxos's golden has
//!   the same difference for the same reason.
//!
//! **What is not here** is the slice, stated in `clean.tla`'s header and in
//! `rewrite.md`: the base protocol, the client and execution layers,
//! reconfiguration and views. A reader who expects `oepoch`, `new_view` or
//! `Resubmit` should read those first.

use vstd::prelude::*;

verus! {
    pub enum LJstate {
        Ready,
        Recovery,
        AfterBeginRecovery,
        AfterPrepare,
        AfterAccept,
    }

    pub struct LCommand {
        pub cmd_id: int,
        pub key: int,
    }

    /// Wire messages. Routing lives on the packet, not in the payload.
    pub enum LMessage {
        Brq { mjepoch: int },
        Brp { maccepted_ballot: int, maccepted_value: Set<LCommand> },
        Pq { mballot: int },
        Pp { maccepted_ballot: int, maccepted_value: Set<LCommand>, mballot: int },
        Aq { mballot: int, mvalue: Set<LCommand> },
        Ap { mballot: int },
    }

    /// A message addressed to a peer.
    pub struct LPacket {
        pub dst: int,
        pub msg: LMessage,
    }

    /// This node's state.
    pub struct LState {
        pub jstate: LJstate,
        pub jepoch: int,
        pub max_seen_ballot: int,
        pub accepted_ballot: int,
        pub accepted_value: Set<LCommand>,
        pub recovery_set: Set<int>,
        pub prep_rcvd: Set<int>,
        pub accept_rcvd: Set<int>,
        pub chosen_value: Set<LCommand>,
        pub highest_seen_ballot: int,
        pub highest_seen_value: Set<LCommand>,
    }

    /// Protocol constants, including this node's own identity.
    pub struct LConstants {
        pub server: Set<int>,
        pub max_ballot: int,
        pub node_id: int,
    }

    pub open spec fn LIsQuorum(c: LConstants, s_arg: Set<int>) -> bool {
        (s_arg.len() as int) * 2 > (c.server.len() as int)
    }

    pub open spec fn LInit(s: LState, c: LConstants) -> bool {
        &&& s.jstate is Ready
        &&& s.jepoch == 0
        &&& s.max_seen_ballot == 0
        &&& s.accepted_ballot == 0
        &&& s.accepted_value == Set::<LCommand>::empty()
        &&& s.recovery_set == Set::<int>::empty()
        &&& s.prep_rcvd == Set::<int>::empty()
        &&& s.accept_rcvd == Set::<int>::empty()
        &&& s.chosen_value == Set::<LCommand>::empty()
        &&& s.highest_seen_ballot == 0
        &&& s.highest_seen_value == Set::<LCommand>::empty()
    }

    pub open spec fn LSendBeginRecovery(
        s: LState,
        s_: LState,
        c: LConstants,
        b: int,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s.jstate is Ready
        &&& b > s.jepoch
        &&& s_.jepoch == b
        &&& s_.jstate is Recovery
        &&& s_.recovery_set == Set::<int>::empty()
        &&& s_.highest_seen_ballot == 0
        &&& s_.highest_seen_value == Set::<LCommand>::empty()
        &&& sent_packets == c.server.map(|d: int| LPacket { dst: d, msg: LMessage::Brq { mjepoch: b } })
        &&& s_.max_seen_ballot == s.max_seen_ballot
        &&& s_.accepted_ballot == s.accepted_ballot
        &&& s_.accepted_value == s.accepted_value
        &&& s_.prep_rcvd == s.prep_rcvd
        &&& s_.accept_rcvd == s.accept_rcvd
        &&& s_.chosen_value == s.chosen_value
    }

    pub open spec fn LHandleBeginRecoveryReq(
        s: LState,
        s_: LState,
        c: LConstants,
        src: int,
        mjepoch: int,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s_.jstate is Recovery
        &&& sent_packets == set![LPacket { dst: src, msg: LMessage::Brp { maccepted_ballot: s.accepted_ballot, maccepted_value: s.accepted_value } }]
        &&& s_.jepoch == s.jepoch
        &&& s_.max_seen_ballot == s.max_seen_ballot
        &&& s_.accepted_ballot == s.accepted_ballot
        &&& s_.accepted_value == s.accepted_value
        &&& s_.recovery_set == s.recovery_set
        &&& s_.prep_rcvd == s.prep_rcvd
        &&& s_.accept_rcvd == s.accept_rcvd
        &&& s_.chosen_value == s.chosen_value
        &&& s_.highest_seen_ballot == s.highest_seen_ballot
        &&& s_.highest_seen_value == s.highest_seen_value
    }

    pub open spec fn LHandleBeginRecoveryResp(
        s: LState,
        s_: LState,
        c: LConstants,
        src: int,
        maccepted_ballot: int,
        maccepted_value: Set<LCommand>,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s.jstate is Recovery
        &&& s_.recovery_set == s.recovery_set.union(set![src])
        &&& s_.highest_seen_ballot == if maccepted_ballot > s.highest_seen_ballot { maccepted_ballot } else { s.highest_seen_ballot }
        &&& s_.highest_seen_value == if maccepted_ballot > s.highest_seen_ballot { maccepted_value } else { s.highest_seen_value }
        &&& sent_packets == Set::<LPacket>::empty()
        &&& s_.jstate == s.jstate
        &&& s_.jepoch == s.jepoch
        &&& s_.max_seen_ballot == s.max_seen_ballot
        &&& s_.accepted_ballot == s.accepted_ballot
        &&& s_.accepted_value == s.accepted_value
        &&& s_.prep_rcvd == s.prep_rcvd
        &&& s_.accept_rcvd == s.accept_rcvd
        &&& s_.chosen_value == s.chosen_value
    }

    pub open spec fn LCompleteBeginRecovery(
        s: LState,
        s_: LState,
        c: LConstants,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s.jstate is Recovery
        &&& LIsQuorum(c, s.recovery_set)
        &&& s_.chosen_value == s.highest_seen_value
        &&& s_.jstate is AfterBeginRecovery
        &&& s_.prep_rcvd == Set::<int>::empty()
        &&& sent_packets == Set::<LPacket>::empty()
        &&& s_.jepoch == s.jepoch
        &&& s_.max_seen_ballot == s.max_seen_ballot
        &&& s_.accepted_ballot == s.accepted_ballot
        &&& s_.accepted_value == s.accepted_value
        &&& s_.recovery_set == s.recovery_set
        &&& s_.accept_rcvd == s.accept_rcvd
        &&& s_.highest_seen_ballot == s.highest_seen_ballot
        &&& s_.highest_seen_value == s.highest_seen_value
    }

    pub open spec fn LSendPrepare(
        s: LState,
        s_: LState,
        c: LConstants,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s.jstate is AfterBeginRecovery
        &&& sent_packets == c.server.map(|d: int| LPacket { dst: d, msg: LMessage::Pq { mballot: s.jepoch } })
        &&& s_.jstate == s.jstate
        &&& s_.jepoch == s.jepoch
        &&& s_.max_seen_ballot == s.max_seen_ballot
        &&& s_.accepted_ballot == s.accepted_ballot
        &&& s_.accepted_value == s.accepted_value
        &&& s_.recovery_set == s.recovery_set
        &&& s_.prep_rcvd == s.prep_rcvd
        &&& s_.accept_rcvd == s.accept_rcvd
        &&& s_.chosen_value == s.chosen_value
        &&& s_.highest_seen_ballot == s.highest_seen_ballot
        &&& s_.highest_seen_value == s.highest_seen_value
    }

    pub open spec fn LHandlePrepareReq(
        s: LState,
        s_: LState,
        c: LConstants,
        src: int,
        mballot: int,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& mballot >= s.max_seen_ballot
        &&& s_.max_seen_ballot == mballot
        &&& sent_packets == set![LPacket { dst: src, msg: LMessage::Pp { mballot: mballot, maccepted_ballot: s.accepted_ballot, maccepted_value: s.accepted_value } }]
        &&& s_.jstate == s.jstate
        &&& s_.jepoch == s.jepoch
        &&& s_.accepted_ballot == s.accepted_ballot
        &&& s_.accepted_value == s.accepted_value
        &&& s_.recovery_set == s.recovery_set
        &&& s_.prep_rcvd == s.prep_rcvd
        &&& s_.accept_rcvd == s.accept_rcvd
        &&& s_.chosen_value == s.chosen_value
        &&& s_.highest_seen_ballot == s.highest_seen_ballot
        &&& s_.highest_seen_value == s.highest_seen_value
    }

    pub open spec fn LHandlePrepareResp(
        s: LState,
        s_: LState,
        c: LConstants,
        src: int,
        maccepted_ballot: int,
        maccepted_value: Set<LCommand>,
        mballot: int,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& mballot == s.jepoch
        &&& s_.prep_rcvd == s.prep_rcvd.union(set![src])
        &&& s_.highest_seen_ballot == if maccepted_ballot > s.highest_seen_ballot { maccepted_ballot } else { s.highest_seen_ballot }
        &&& s_.highest_seen_value == if maccepted_ballot > s.highest_seen_ballot { maccepted_value } else { s.highest_seen_value }
        &&& sent_packets == Set::<LPacket>::empty()
        &&& s_.jstate == s.jstate
        &&& s_.jepoch == s.jepoch
        &&& s_.max_seen_ballot == s.max_seen_ballot
        &&& s_.accepted_ballot == s.accepted_ballot
        &&& s_.accepted_value == s.accepted_value
        &&& s_.recovery_set == s.recovery_set
        &&& s_.accept_rcvd == s.accept_rcvd
        &&& s_.chosen_value == s.chosen_value
    }

    pub open spec fn LCompletePrepare(
        s: LState,
        s_: LState,
        c: LConstants,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s.jstate is AfterBeginRecovery
        &&& LIsQuorum(c, s.prep_rcvd)
        &&& s_.chosen_value == if s.highest_seen_ballot > 0 { s.highest_seen_value } else { s.chosen_value }
        &&& s_.jstate is AfterPrepare
        &&& s_.accept_rcvd == Set::<int>::empty()
        &&& sent_packets == Set::<LPacket>::empty()
        &&& s_.jepoch == s.jepoch
        &&& s_.max_seen_ballot == s.max_seen_ballot
        &&& s_.accepted_ballot == s.accepted_ballot
        &&& s_.accepted_value == s.accepted_value
        &&& s_.recovery_set == s.recovery_set
        &&& s_.prep_rcvd == s.prep_rcvd
        &&& s_.highest_seen_ballot == s.highest_seen_ballot
        &&& s_.highest_seen_value == s.highest_seen_value
    }

    pub open spec fn LSendAccept(
        s: LState,
        s_: LState,
        c: LConstants,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s.jstate is AfterPrepare
        &&& sent_packets == c.server.map(|d: int| LPacket { dst: d, msg: LMessage::Aq { mballot: s.jepoch, mvalue: s.chosen_value } })
        &&& s_.jstate == s.jstate
        &&& s_.jepoch == s.jepoch
        &&& s_.max_seen_ballot == s.max_seen_ballot
        &&& s_.accepted_ballot == s.accepted_ballot
        &&& s_.accepted_value == s.accepted_value
        &&& s_.recovery_set == s.recovery_set
        &&& s_.prep_rcvd == s.prep_rcvd
        &&& s_.accept_rcvd == s.accept_rcvd
        &&& s_.chosen_value == s.chosen_value
        &&& s_.highest_seen_ballot == s.highest_seen_ballot
        &&& s_.highest_seen_value == s.highest_seen_value
    }

    pub open spec fn LHandleAcceptReq(
        s: LState,
        s_: LState,
        c: LConstants,
        src: int,
        mballot: int,
        mvalue: Set<LCommand>,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& mballot >= s.max_seen_ballot
        &&& s_.max_seen_ballot == mballot
        &&& s_.accepted_ballot == mballot
        &&& s_.accepted_value == mvalue
        &&& sent_packets == set![LPacket { dst: src, msg: LMessage::Ap { mballot: mballot } }]
        &&& s_.jstate == s.jstate
        &&& s_.jepoch == s.jepoch
        &&& s_.recovery_set == s.recovery_set
        &&& s_.prep_rcvd == s.prep_rcvd
        &&& s_.accept_rcvd == s.accept_rcvd
        &&& s_.chosen_value == s.chosen_value
        &&& s_.highest_seen_ballot == s.highest_seen_ballot
        &&& s_.highest_seen_value == s.highest_seen_value
    }

    pub open spec fn LHandleAcceptResp(
        s: LState,
        s_: LState,
        c: LConstants,
        src: int,
        mballot: int,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& mballot == s.jepoch
        &&& s_.accept_rcvd == s.accept_rcvd.union(set![src])
        &&& sent_packets == Set::<LPacket>::empty()
        &&& s_.jstate == s.jstate
        &&& s_.jepoch == s.jepoch
        &&& s_.max_seen_ballot == s.max_seen_ballot
        &&& s_.accepted_ballot == s.accepted_ballot
        &&& s_.accepted_value == s.accepted_value
        &&& s_.recovery_set == s.recovery_set
        &&& s_.prep_rcvd == s.prep_rcvd
        &&& s_.chosen_value == s.chosen_value
        &&& s_.highest_seen_ballot == s.highest_seen_ballot
        &&& s_.highest_seen_value == s.highest_seen_value
    }

    pub open spec fn LCompleteAccept(
        s: LState,
        s_: LState,
        c: LConstants,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s.jstate is AfterPrepare
        &&& LIsQuorum(c, s.accept_rcvd)
        &&& s_.jstate is AfterAccept
        &&& sent_packets == Set::<LPacket>::empty()
        &&& s_.jepoch == s.jepoch
        &&& s_.max_seen_ballot == s.max_seen_ballot
        &&& s_.accepted_ballot == s.accepted_ballot
        &&& s_.accepted_value == s.accepted_value
        &&& s_.recovery_set == s.recovery_set
        &&& s_.prep_rcvd == s.prep_rcvd
        &&& s_.accept_rcvd == s.accept_rcvd
        &&& s_.chosen_value == s.chosen_value
        &&& s_.highest_seen_ballot == s.highest_seen_ballot
        &&& s_.highest_seen_value == s.highest_seen_value
    }

    pub open spec fn LFinishRecovery(
        s: LState,
        s_: LState,
        c: LConstants,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s.jstate is AfterAccept
        &&& s_.jstate is Ready
        &&& s_.recovery_set == Set::<int>::empty()
        &&& s_.prep_rcvd == Set::<int>::empty()
        &&& s_.accept_rcvd == Set::<int>::empty()
        &&& sent_packets == Set::<LPacket>::empty()
        &&& s_.jepoch == s.jepoch
        &&& s_.max_seen_ballot == s.max_seen_ballot
        &&& s_.accepted_ballot == s.accepted_ballot
        &&& s_.accepted_value == s.accepted_value
        &&& s_.chosen_value == s.chosen_value
        &&& s_.highest_seen_ballot == s.highest_seen_ballot
        &&& s_.highest_seen_value == s.highest_seen_value
    }

    /// Dispatch on the received message. Delivery and the tag are the
    /// framework's; each handler states only its own conditions.
    pub open spec fn LHandleMessage(
        s: LState,
        s_: LState,
        c: LConstants,
        src: int,
        msg: LMessage,
        sent_packets: Set<LPacket>,
    ) -> bool {
        match msg {
            LMessage::Brq { mjepoch } =>
                LHandleBeginRecoveryReq(s, s_, c, src, mjepoch, sent_packets),
            LMessage::Brp { maccepted_ballot, maccepted_value } =>
                LHandleBeginRecoveryResp(s, s_, c, src, maccepted_ballot, maccepted_value, sent_packets),
            LMessage::Pq { mballot } =>
                LHandlePrepareReq(s, s_, c, src, mballot, sent_packets),
            LMessage::Pp { maccepted_ballot, maccepted_value, mballot } =>
                LHandlePrepareResp(s, s_, c, src, maccepted_ballot, maccepted_value, mballot, sent_packets),
            LMessage::Aq { mballot, mvalue } =>
                LHandleAcceptReq(s, s_, c, src, mballot, mvalue, sent_packets),
            LMessage::Ap { mballot } =>
                LHandleAcceptResp(s, s_, c, src, mballot, sent_packets),
        }
    }

    pub open spec fn LNext(
        s: LState,
        s_: LState,
        c: LConstants,
        sent_packets: Set<LPacket>,
    ) -> bool {
        ||| (exists|b: int|
                0 <= b && b <= c.max_ballot && LSendBeginRecovery(s, s_, c, b, sent_packets))
        ||| LCompleteBeginRecovery(s, s_, c, sent_packets)
        ||| LSendPrepare(s, s_, c, sent_packets)
        ||| LCompletePrepare(s, s_, c, sent_packets)
        ||| LSendAccept(s, s_, c, sent_packets)
        ||| LCompleteAccept(s, s_, c, sent_packets)
        ||| LFinishRecovery(s, s_, c, sent_packets)
        ||| (exists|src: int, msg: LMessage|
                LHandleMessage(s, s_, c, src, msg, sent_packets))
    }
}
